// Independent DR-0166 reconstruction. No Rust encoder or generated bytes are
// invoked. These are candidate transport frames, never an authenticated cut.
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';

const uint = (n, width) => {
  const bytes = Buffer.alloc(width);
  let value = BigInt(n);
  for (let i = 0; i < width; i++) { bytes[i] = Number(value & 255n); value >>= 8n; }
  assert.equal(value, 0n);
  return bytes;
};
const frame = (type, fields) => Buffer.concat([
  Buffer.from('SNRE'), uint(type, 2), uint(1, 2), uint(fields.length, 2),
  ...fields.flatMap(([id, bytes]) => [uint(id, 2), uint(bytes.length, 4), bytes]),
]);
const digest = (bytes) => frame(0x0103, [[1, uint(1, 2)], [2, bytes]]);
const markedDigest = (byte) => digest(Buffer.alloc(32, byte));
const sha = (bytes) => createHash('sha256').update(bytes).digest();
const chain = Buffer.from('portable-vectors');
const effectsHash = (bytes) => sha(frame(0x1001, [
  [1, uint(1, 2)], [2, uint(3, 2)], [3, uint(1, 2)],
  [4, chain], [5, uint(3, 4)], [6, bytes],
]));
const drain = frame(0xd03b, [
  [1, chain], [2, uint(3, 4)], [3, uint(9, 8)], [4, Buffer.alloc(32, 0x14)],
  [5, Buffer.alloc(32, 0x15)], [6, uint(2, 8)], [7, uint(3, 8)],
  [8, uint(0, 8)], [9, markedDigest(0x11)],
]);
const identity = frame(0x6490, [[1, drain], [2, uint(7, 8)],
  [3, markedDigest(0x12)], [4, markedDigest(0x13)]]);
const identityRoot = effectsHash(identity);
const state = frame(0x6491, [[1, uint(1, 2)], [2, uint(0, 2)]]);
const tombstone = frame(0x6491, [[1, uint(1, 2)], [2, uint(1, 2)]]);
const item = frame(0x6492, [[1, digest(identityRoot)], [2, uint(1, 2)],
  [3, uint(0, 8)], [4, uint(1, 2)], [5, Buffer.from('app/key')], [6, state],
  [7, uint(0, 8)], [8, Buffer.from([0xa1, 0xa2])], [9, uint(1, 2)]]);
const manifest = frame(0x6493, [[1, identity], [2, uint(1, 8)], [3, uint(0, 8)],
  [4, uint(0, 8)], [5, uint(0, 8)], [6, markedDigest(0x17)]]);
const hashStep = frame(0x6495, [[1, digest(identityRoot)], [2, uint(1, 8)],
  [3, digest(identityRoot)], [4, item]]);
const firstStepRoot = effectsHash(hashStep);
const progress = frame(0x6494, [[1, digest(identityRoot)], [2, Buffer.from('mem/portable-test')],
  [3, Buffer.alloc(32, 0x14)], [4, uint(1, 8)], [5, uint(4, 8)], [6, uint(0, 2)],
  [7, uint(1, 8)], [8, uint(0, 8)], [9, uint(1, 8)], [10, digest(firstStepRoot)],
  [11, item], [12, uint(1, 8)], [13, uint(0, 8)], [14, uint(0, 8)], [15, uint(0, 8)],
  [16, Buffer.alloc(0)]]);
const expected = {
  identity: '4ae1364d4cc5d738f8d28398cbf5e3456f11a7ac0cad26813d73fc4854ee5ce2',
  state: 'a69598e2550231fd29badb10bc6693f414b1fbfcefbda923de1894ddc9cdae9a',
  tombstone: 'e4608b50a109ab1930362dd7d91a368df1c70a6037a73f818a8080c770a65230',
  item: 'b537b3dbd46b0ad7077cd4cf941dc148c77baad2067fff13e60ff64e8b4f6333',
  manifest: '7875d834a587f818ecfcbfc2e5d579f9747b2e3fc40a7e9804827fd130e75e6e',
  hashStep: '104ab01d79d78338ea57de6a47ca560bd7b18ca626e51ec0d181d764b0ad60ed',
  progress: '4c195531b3fca41b0d7be6e3feb0a8f29bc56f642b9a976f3a1f2ead2e450671',
};
for (const [name, bytes] of Object.entries({ identity, state, tombstone, item, manifest, hashStep, progress })) {
  const hash = sha(bytes).toString('hex');
  assert.equal(hash, expected[name]);
  console.log(JSON.stringify({ name, length: bytes.length, sha256: hash }));
}
assert.equal(identityRoot.toString('hex'), 'd915ef86d6052b224eb5e166ef09a212cc81807ee52afe9c0adf056eab5bbf1e');
assert.equal(firstStepRoot.toString('hex'), 'c9eff8a83ee1d29f3b64741c324a3b06b5bd4498741e85633d03bbf766a57aba');
console.log(JSON.stringify({ name: 'identityRoot', digest: identityRoot.toString('hex') }));
